mapper.select:
SELECT COUNT(*) > 0
FROM lecture
WHERE lecture_id = #{lectureId}

SELECT COALESCE(
ROUND(
CASE
WHEN total_materials.total_count = 0 THEN 0.0
ELSE (COALESCE(completed_materials.completed_count, 0) * 100.0 / total_materials.total_count)
END, 1
), 0.0
) as progressRate
FROM (
SELECT COUNT(*) as total_count
FROM lecture_material lm
INNER JOIN lecture_content lc ON lm.lecture_material_id = lc.lecture_material_id
INNER JOIN lecture_chapter lch ON lc.lecture_chapter_id = lch.lecture_chapter_id
WHERE lch.lecture_id = #{lectureId}
) total_materials
LEFT JOIN (
SELECT COUNT(DISTINCT cm.material_id) as completed_count
FROM completed_materials cm
WHERE cm.user_id = #{userId} AND cm.lecture_id = #{lectureId}
) completed_materials ON 1=1

