mapper.insert:
INSERT INTO lecture_field (
    lecture_id,
    interested_id
) 
SELECT #{lectureId}, #{interestedId}
WHERE EXISTS (
    SELECT 1 FROM lecture WHERE lecture_id = #{lectureId}
)
AND EXISTS (
    SELECT 1 FROM interested WHERE interested_id = #{interestedId}
)
AND NOT EXISTS (
    SELECT 1 FROM lecture_field 
    WHERE lecture_id = #{lectureId} 
    AND interested_id = #{interestedId}
)

mapper.select:
SELECT interested_id
FROM lecture_field
WHERE lecture_id = #{lectureId}
